import{_ as s,C as a,o as l,c as n,a2 as t,E as o}from"./chunks/framework.BSaF8iZ6.js";const _=JSON.parse('{"title":"Seller & Product Flagging","description":"","frontmatter":{},"headers":[],"relativePath":"moderation/seller-product-flagging.md","filePath":"moderation/seller-product-flagging.md","lastUpdated":1789411447000}'),g={name:"moderation/seller-product-flagging.md"};function i(d,e,c,p,h,u){const r=a("ImagePopup");return l(),n("div",null,[e[0]||(e[0]=t('<h1 id="seller-product-flagging" tabindex="-1">Seller &amp; Product Flagging <a class="header-anchor" href="#seller-product-flagging" aria-label="Permalink to &quot;Seller &amp; Product Flagging&quot;">​</a></h1><div class="page-roles"><span class="role role--customer">Customer</span><span class="role role--admin">Admin</span></div><p>Customers can report a problem with a product or a seller, such as a damaged, wrong or overpriced product. The admin chooses the reasons customers pick from and reviews every report.</p><h2 id="report-a-product" tabindex="-1">Report a product <a class="header-anchor" href="#report-a-product" aria-label="Permalink to &quot;Report a product&quot;">​</a></h2><p>Customers who have ordered a product from a seller can report it once.</p><ol><li>Sign in to your customer account.</li><li>On the product&#39;s page, or on the seller&#39;s offer in the offers page, click <strong>Report Product</strong>.</li><li>Choose a <strong>Reason</strong>. To describe something else, choose <strong>Other Reason</strong> and type it.</li><li>Click <strong>Submit</strong>.</li></ol>',6)),o(r,{src:"/images/seller-product-flagging/report-product.png",alt:"The Report Product form"}),e[1]||(e[1]=t('<p>You&#39;ll see <strong>Product Reported successfully</strong>. The seller and the store admin each receive a <strong>Product Report Notification</strong> email.</p><h2 id="report-a-seller" tabindex="-1">Report a seller <a class="header-anchor" href="#report-a-seller" aria-label="Permalink to &quot;Report a seller&quot;">​</a></h2><p>Customers who have ordered from a seller can report the seller once.</p><ol><li>Sign in to your customer account.</li><li>On the seller&#39;s shop page, click <strong>Report Issue</strong>.</li><li>Choose a <strong>Reason</strong>, or <strong>Other Reason</strong>.</li><li>Click <strong>Submit</strong>.</li></ol>',4)),o(r,{src:"/images/seller-product-flagging/report-seller.png",alt:"The Report Issue form on a seller's shop page"}),e[2]||(e[2]=t('<p>You&#39;ll see <strong>Seller reported successfully</strong>. The seller and the store admin each receive a <strong>Seller Report Notification</strong> email.</p><table tabindex="0"><thead><tr><th>Message</th><th>What it means</th></tr></thead><tbody><tr><td><strong>You need to login to report …</strong></td><td>Sign in first.</td></tr><tr><td><strong>You have already reported …</strong></td><td>You can report each product or seller once.</td></tr><tr><td><strong>You cannot report … without placing an order</strong></td><td>Only customers who ordered can report.</td></tr></tbody></table><h2 id="flag-reasons" tabindex="-1">Flag reasons <a class="header-anchor" href="#flag-reasons" aria-label="Permalink to &quot;Flag reasons&quot;">​</a></h2><ol><li>Go to <strong>Marketplace &gt;&gt; Configure &gt;&gt; Flag Reasons</strong>.</li><li>Click <strong>Create Reason</strong>.</li><li>In <strong>Label</strong>, enter the <strong>Admin</strong> name, and the reason customers see in each language.</li><li>In <strong>General</strong>, choose the <strong>Type</strong>: <strong>Product</strong> or <strong>Seller</strong>.</li><li>Switch <strong>Status</strong> on so customers can choose it.</li><li>Click <strong>Save Reason</strong>.</li></ol>',4)),o(r,{src:"/images/seller-product-flagging/flag-reasons.png",alt:"The Flag Reasons list"}),o(r,{src:"/images/seller-product-flagging/reason-create.png",alt:"The Create Reason form"}),e[3]||(e[3]=t('<p>The list shows each reason&#39;s <strong>Id</strong>, <strong>Name</strong>, <strong>Type</strong> and <strong>Status</strong>, with icons to edit or delete it. To switch several reasons on or off, tick them and use <strong>Select Action &gt;&gt; Update Status</strong>, then <strong>Active</strong> or <strong>Disable</strong>. To delete several, use <strong>Select Action &gt;&gt; Delete</strong>.</p><p>The marketplace starts with these reasons:</p><ul><li><strong>Product:</strong> Duplicate product, Damaged product, Poor product quality, Over price product, Missing product parts, Receive wrong product.</li><li><strong>Seller:</strong> Duplicate product sold by seller, Damaged product sold by seller, Poor product quality sold by seller, Over price product sold by seller, Wrong product sold by seller.</li></ul><h2 id="review-reports" tabindex="-1">Review reports <a class="header-anchor" href="#review-reports" aria-label="Permalink to &quot;Review reports&quot;">​</a></h2><ul><li><strong>Seller reports</strong> — go to <strong>Marketplace &gt;&gt; Sellers</strong> and click <strong>Flags</strong> on the seller&#39;s row. The <strong>Seller Flags</strong> list shows the customer, their email, the reason and the date.</li><li><strong>Product reports</strong> — go to <strong>Marketplace &gt;&gt; Catalog &gt;&gt; Products</strong> and click <strong>Total Flags</strong> under the product. The <strong>Product Flags</strong> list shows the same details.</li></ul>',5)),o(r,{src:"/images/seller-product-flagging/seller-flags.png",alt:"The Seller Flags list for a seller"}),e[4]||(e[4]=t('<p>Reports can&#39;t be deleted. The flags count on the sellers list covers the last 90 days and is updated once a day, or when you use <strong>Refresh Account Health</strong>. The <strong>Seller Flags</strong> list shows every report.</p><h2 id="what-reports-change" tabindex="-1">What reports change <a class="header-anchor" href="#what-reports-change" aria-label="Permalink to &quot;What reports change&quot;">​</a></h2><ul><li><strong>Seller reports</strong> count towards the seller&#39;s <a href="./../sellers/seller-account-health">Account Health</a> for 90 days.</li><li>When <strong>Show Red Flag</strong> is on and a seller has more reports than the store&#39;s limit, a red flag appears next to their name on their shop page. The red flag counts every report the seller has received.</li><li><strong>Product reports</strong> are counted and emailed, but don&#39;t change anything else.</li></ul><p>Nothing is hidden or suspended automatically. Use <a href="./../sellers/seller-management">Seller Management</a> to act on a seller.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Turning reporting on or off, <strong>Show Red Flag</strong> and the red flag limit are in <a href="./../configuration/moderation-and-health">Moderation &amp; Health settings</a>.</p>',6))])}const f=s(g,[["render",i]]);export{_ as __pageData,f as default};
